steps.code:
# Parse the archive file content into (title, artist) pairs
archive_songs = []
for line in archive_file['content'].splitlines():
    line = line.strip()
    if line.startswith('- '):
        song_str = line[2:]
        if ' by ' in song_str:
            title, artist = song_str.rsplit(' by ', 1)
            archive_songs.append((title.strip(), artist.strip()))
print(archive_songs)

